LESSONS["1B"].vocab=[{/* TODO(fa-review) */ "en":"level-headed","type":"word","fa":"باذکاوت، آروم و خونسرد در شرایط سخت","ex":"During high-pressure meetings, our manager always remains level-headed.","collocations":[{"en":"a level-headed decision","fa":"تصمیم عاقلانه و خونسردانه"},{"en":"remain level-headed","fa":"خونسرد و عاقل ماندن"}],"chunks":[{"en":"keep a cool head","fa":"خونسردی به خرج دادن"},{"en":"think clearly under pressure","fa":"زیر فشار واضح فکر کردن"}]},{/* TODO(fa-review) */ "en":"thin-skinned","type":"word","fa":"زودرنج و حساس به انتقاد","ex":"It is quite difficult to give constructive feedback to someone who is thin-skinned.","collocations":[{"en":"a thin-skinned person","fa":"آدم زودرنج"},{"en":"overly thin-skinned","fa":"بیش از حد زودرنج"}],"chunks":[{"en":"take criticism well","fa":"انتقاد را خوب پذیرفتن"},{"en":"be easily offended","fa":"زود آزرده شدن"}]},{/* TODO(fa-review) */ "en":"have a heart of gold","type":"idiom","fa":"قلب فوق‌العاده مهربانی داشتن","ex":"Although he looks stern on the outside, our neighbor has a heart of gold.","collocations":[{"en":"genuine kindness","fa":"مهربانی واقعی"},{"en":"warm-hearted","fa":"خون‌گرم و مهربان"}],"chunks":[{"en":"be kind to others","fa":"با دیگران مهربان بودن"},{"en":"help people in need","fa":"به نیازمندان کمک کردن"}]},{/* TODO(fa-review) */ "en":"speak one's mind","type":"chunk","fa":"رک، صریح و بدون ترس ابراز نظر کردن","ex":"She is never afraid to speak her mind during team planning sessions.","collocations":[{"en":"speak frankly","fa":"رک و راست حرف زدن"},{"en":"voice your opinion","fa":"نظرت را بیان کردن"}],"chunks":[{"en":"say what you think","fa":"حرف دلت را زدن"},{"en":"hold nothing back","fa":"چیزی را از خود نگه نداشتن"}]},{/* TODO(fa-review) */ "en":"set in one's ways","type":"idiom","fa":"غیرقابل انعطاف و پایبند به عادات قدیمی","ex":"My grandfather is firmly set in his ways and refuses to use modern smartphones.","collocations":[{"en":"resist new ideas","fa":"ایده‌های تازه را نپذیرفتن"},{"en":"unwilling to change","fa":"حاضر به تغییر نبودن"}],"chunks":[{"en":"stuck in a routine","fa":"گیر روتین بودن"},{"en":"afraid of change","fa":"از تغییر ترسیدن"}]},{/* TODO(fa-review) */ "en":"keep to oneself","type":"chunk","fa":"گوشه‌گیر بودن و تمایل به حریم شخصی","ex":"He is a polite colleague, but after work hours he prefers to keep to himself.","collocations":[{"en":"a private person","fa":"آدم باحریم"},{"en":"value privacy","fa":"برای حریم شخصی ارزش قائل شدن"}],"chunks":[{"en":"keep your distance","fa":"فاصله خود را حفظ کردن"},{"en":"prefer solitude","fa":"تنهایی را ترجیح دادن"}]},{/* TODO(fa-review) */ "en":"quick-witted","type":"word","fa":"تیزهوش و حاضرجواب","ex":"Her quick-witted responses made the panel discussion both engaging and informative.","collocations":[{"en":"a quick-witted reply","fa":"پاسخ حاضرجوابانه"},{"en":"a sharp mind","fa":"ذهن تیز"}],"chunks":[{"en":"think on your feet","fa":"در لحظه و بدون آمادگی جواب دادن"},{"en":"come up with a quick answer","fa":"سریع یک پاسخ پیدا کردن"}]},{/* TODO(fa-review) */ "en":"stand up for someone","type":"chunk","fa":"از کسی دفاع و حمایت کردن","ex":"A true friend will always stand up for you when others make unfair assumptions.","collocations":[{"en":"defend a friend","fa":"از دوست دفاع کردن"},{"en":"offer support","fa":"حمایت کردن"}],"chunks":[{"en":"have someone's back","fa":"پشتیبان کسی بودن"},{"en":"do the right thing","fa":"کار درست را انجام دادن"}]},{/* TODO(fa-review) */ "en":"two-faced","type":"word","fa":"دوپیکر، منافق و دو‌رو","ex":"Working with a person who is two-faced destroys trust within an office team.","collocations":[{"en":"a two-faced colleague","fa":"همکار دوپیکر"},{"en":"behind someone's back","fa":"پشت سر کسی"}],"chunks":[{"en":"say one thing and do another","fa":"حرف و عملش یکی نبودن"},{"en":"talk behind people's backs","fa":"پشت سر مردم حرف زدن"}]},{/* TODO(fa-review) */ "en":"light-hearted","type":"word","fa":"شاد، بی‌خیال و فارغ از جدی بودن زیاد","ex":"We enjoyed a light-hearted conversation over coffee after finishing the presentation.","collocations":[{"en":"a light-hearted conversation","fa":"گفتگوی شاد و خودمانی"},{"en":"in a light-hearted way","fa":"به شکل شوخ و طنز"}],"chunks":[{"en":"have a good laugh","fa":"با هم خندیدن"},{"en":"make a joke","fa":"شوخی کردن"}]},{/* TODO(fa-review) */ "en":"down-to-earth","type":"word","fa":"خاکی، خاکی‌منش و واقع‌بین","ex":"He is very down-to-earth, so he always gives practical advice when I have problems.","collocations":[{"en":"a down-to-earth person","fa":"آدم خاکی و واقعی"},{"en":"practical advice","fa":"توصیه عملی"}],"chunks":[{"en":"stay humble","fa":"فروتن ماندن"},{"en":"tell it like it is","fa":"واقعیت را بی‌تعارف گفتن"}]},{/* TODO(fa-review) */ "en":"count on someone","type":"chunk","fa":"روی کسی حساب کردن / اعتماد کامل داشتن","ex":"She is totally reliable, so you can always count on her during a crisis.","collocations":[{"en":"a reliable person","fa":"آدم قابل اعتماد"},{"en":"depend on someone","fa":"به کسی تکیه کردن"}],"chunks":[{"en":"be there for someone","fa":"در سختی کنار کسی بودن"},{"en":"keep your word","fa":"به حرفت عمل کردن"}]},{/* TODO(fa-review) */ "en":"a sense of humor","type":"collocation","fa":"حس شوخ‌طبعی","ex":"Our teacher has a great sense of humor, which makes her classes lively and fun.","collocations":[{"en":"a good sense of humor","fa":"شوخ‌طبعی خوب"},{"en":"share a joke","fa":"شوخی را با هم گفتن"}],"chunks":[{"en":"see the funny side","fa":"بعد خنده‌دار ماجرا را دیدن"},{"en":"laugh at yourself","fa":"به خودت خندیدن"}]},{/* TODO(fa-review) */ "en":"laid-back","type":"word","fa":"بی‌خیال، راحت و آسوده‌خاطر","ex":"My manager is pretty laid-back, so he does not panic when minor issues arise.","collocations":[{"en":"a laid-back attitude","fa":"نگرش راحت و آسوده"},{"en":"stay relaxed","fa":"آرام و ریلکس ماندن"}],"chunks":[{"en":"take it easy","fa":"بی‌خیال بودن"},{"en":"not worry too much","fa":"زیاد نگران نبودن"}]},{/* TODO(fa-review) */ "en":"wear one's heart on one's sleeve","type":"idiom","fa":"احساسات خود را رو بازی کردن و بر ملا ساختن","ex":"You always know how he feels because he wears his heart on his sleeve.","collocations":[{"en":"show emotions openly","fa":"احساسات را آشکارا نشان دادن"},{"en":"hide your feelings","fa":"احساساتت را پنهان کردن"}],"chunks":[{"en":"show how you feel","fa":"احساست را نشان دادن"},{"en":"keep emotions private","fa":"احساسات را خصوصی نگه داشتن"}]},{/* TODO(fa-review) */ "en":"a workaholic","type":"word","fa":"معتاد به کار / پرکار خستگی‌ناپذیر","ex":"She is a bit of a workaholic and finds it extremely difficult to relax on weekends.","collocations":[{"en":"a born workaholic","fa":"کار معتاد ذاتی"},{"en":"work long hours","fa":"ساعت‌های طولانی کار کردن"}],"chunks":[{"en":"take a break","fa":"استراحت کردن"},{"en":"balance work and life","fa":"کار و زندگی را متعادل کردن"}]},{/* TODO(fa-review) */ "en":"open-minded","type":"word","fa":"پذیرا، روشن‌فکر و فاقد تعصب","ex":"Having an open-minded leader helps the department adapt to changes quickly.","collocations":[{"en":"an open-minded approach","fa":"رویکرد روشن‌فکرانه"},{"en":"open to new ideas","fa":"پذیرای ایده‌های تازه"}],"chunks":[{"en":"be willing to listen","fa":"حاضر به گوش دادن"},{"en":"consider other views","fa":"نظرهای دیگر را در نظر گرفتن"}]},{/* TODO(fa-review) */ "en":"narrow-minded","type":"word","fa":"تنگ‌نظر و متعصب","ex":"It is challenging to discuss new ideas with a person who is narrow-minded.","collocations":[{"en":"a narrow-minded view","fa":"نگاه تنگ‌نظرانه"},{"en":"reject new ideas","fa":"ایده‌های تازه را رد کردن"}],"chunks":[{"en":"judge too quickly","fa":"سریع قضاوت کردن"},{"en":"stick to old beliefs","fa":"به باورهای قدیمی چسبیدن"}]},{/* TODO(fa-review) */ "en":"easygoing","type":"word","fa":"خوش‌برخورد، آسان‌گیر و سازگار","ex":"He is an easygoing person who gets along well with almost everyone.","collocations":[{"en":"an easygoing personality","fa":"شخصیت آسان‌گیر"},{"en":"get along with everyone","fa":"با همه کنار آمدن"}],"chunks":[{"en":"go with the flow","fa":"همراه جریان بودن"},{"en":"let things go","fa":"چیزها را بی‌خیال شدن"}]},{/* TODO(fa-review) */ "en":"self-centered","type":"word","fa":"خودخواه و خودمحور","ex":"People who are self-centered rarely show genuine concern for the feelings of others.","collocations":[{"en":"a self-centered attitude","fa":"نگاه خودمحور"},{"en":"think only of yourself","fa":"فقط به خودت فکر کردن"}],"chunks":[{"en":"put yourself first","fa":"اول خودت را در نظر گرفتن"},{"en":"care about others","fa":"به دیگران اهمیت دادن"}]}];
LESSONS["1B"].texts=[{"title": "Text 1: Personality Assessments and Human Growth", "topic": "Personality Assessments and Human Growth", "text": "Personality testing is a big industry in modern corporate business. Many companies test job candidates during the hiring process today. These written tests help managers understand candidate behaviors and work habits. Job seekers answer many detailed questions about their daily routines. The test results describe how people perform inside work teams. Employers want to build strong and cooperative office groups. Understanding personality helps colleagues communicate with greater ease and clarity. Personality tests are now common tools across major global corporations.\n\nThe Myers-Briggs test is the most famous personality assessment tool. It divides human beings into sixteen distinct psychological categories. The test measures how individuals receive and process new information. It also examines how people make important decisions under pressure. Some people are labeled as quiet and thoughtful introverts. Other individuals are categorized as outgoing and expressive extraverts. People often share their test results on professional social networks.\n\nHowever, many prominent psychologists question these simple character categories. They argue that human nature is far too complex for simple labels. A person can behave differently in different social environments. Human beings do not fit neatly into rigid personality boxes. Individual test results can change from month to month unexpectedly. Therefore, these popular tests are not always completely reliable. Critics advise managers not to rely heavily on simple test scores.\n\nModern brain science proves that adult human character can change. Neuroscientists call this important biological process neuroplasticity. The human brain forms new neural connections throughout adult life. Learning new skills alters how your physical brain operates daily. Life experiences continuously reshape human behavioral and emotional patterns. Adults are not stuck with their childhood personality traits forever. The adult brain remains flexible and open to new learning.\n\nLong-term research studies prove that character matures over time. Studies show that older adults gradually become more conscientious workers. People usually become much more agreeable as they grow older. Emotional stability also improves significantly during mature adult years. Work obligations help individuals build strong daily self-discipline. Family responsibilities encourage adults to become more patient listeners. Aging brings valuable wisdom and greater emotional self-control.\n\nIndividuals can actively practice and develop new behavioral habits. A disorganized person can learn and apply better daily systems. An impatient worker can practice calm and attentive listening daily. Small daily actions lead to significant character improvements over time. Conscious daily effort helps people overcome negative personal habits. Personal growth requires clear dedication and sustained mental focus. Anyone can choose to cultivate positive new personality traits.\n\nOrganizations benefit greatly when employees develop strong self-awareness. Workers who understand themselves interact with colleagues more effectively. They manage workplace conflicts with greater calm and patience. Teams become much more productive and supportive as a result. Respecting diverse personality styles improves overall office team morale. Positive workplace communication creates a healthy working environment. Companies succeed when they value diverse employee character strengths.\n\nIn conclusion, human personality is not a fixed or permanent state. Our character continues to evolve throughout our entire adult life. Scientific research proves that adults can actively shape their habits. Self-awareness allows us to make positive personal changes every day. With time and dedication, anyone can achieve meaningful personal growth.", /* TODO(fa-review) */ "translationFa": "تست سنجش شخصیت در کسب‌وکار امروزی به صنعتی بزرگ بدل شده است. امروزه شرکت‌های زیادی در فرایند استخدام، داوطلبان را می‌آزمایند. این آزمون‌های کتبی به مدیران کمک می‌کنند رفتار و عادت‌های کاری داوطلبان را بهتر بشناسند. جویندگان کار به پرسش‌های فراوان و جزئی دربارهٔ عادت‌های روزمرهٔ خود پاسخ می‌دهند. نتیجهٔ آزمون نشان می‌دهد هر فرد درون تیم‌های کاری چگونه عمل می‌کند. کارفرمایان می‌خواهند گروه‌های اداری قوی و هماهنگ بسازند. شناخت شخصیت کمک می‌کند همکاران راحت‌تر و شفاف‌تر با هم حرف بزنند. امروزه آزمون‌های شخصیت ابزاری رایج در شرکت‌های بزرگ جهان‌اند.\nآزمون مایرز-بریگز شناخته‌شده‌ترین ابزار سنجش شخصیت است. این آزمون انسان‌ها را به شانزده تیپ روان‌شناختی متمایز تقسیم می‌کند. می‌سنجد که افراد اطلاعات تازه را چگونه دریافت و پردازش می‌کنند و همچنین بررسی می‌کند آدم‌ها زیر فشار چگونه تصمیم‌های مهم می‌گیرند. برخی آرام و متفکر، درون‌گرا برچسب می‌خورند و برخی دیگر اجتماعی و پرحرف، برون‌گرا دسته‌بندی می‌شوند. مردم اغلب نتیجهٔ آزمونشان را در شبکه‌های اجتماعی حرفه‌ای به اشتراک می‌گذارند.\nبااین‌حال، بسیاری از روان‌شناسان سرشناس به این دسته‌بندی‌های سادهٔ شخصیتی تردید دارند. آن‌ها استدلال می‌کنند طبیعت انسان برای برچسب‌های ساده بیش از حد پیچیده است. یک فرد می‌تواند در محیط‌های اجتماعی متفاوت، رفتار متفاوتی داشته باشد. انسان‌ها در قالب‌های خشک شخصیتی نمی‌گنجند. نتیجهٔ آزمون هر کس ممکن است ماه‌به‌ماه و بی‌هشدار تغییر کند. پس این آزمون‌های پرطرفدار همیشه کاملاً قابل‌اعتماد نیستند. منتقدان به مدیران توصیه می‌کنند چندان به نمره‌های سادهٔ آزمون تکیه نکنند.\nدانش امروزی مغز ثابت می‌کند شخصیت آدم بزرگسال می‌تواند تغییر کند. عصب‌شناسان به این فرایند زیستی مهم «انعطاف‌پذیری عصبی» می‌گویند. مغز انسان در سراسر زندگی بزرگسالی پیوندهای عصبی تازه می‌سازد. یادگیری مهارت‌های نو عوض می‌کند که مغز فیزیکی شما روزانه چگونه کار می‌کند. تجربه‌های زندگی پیوسته الگوهای رفتاری و هیجانی انسان را بازمی‌سازند. بزرگسالان تا ابد اسیر ویژگی‌های شخصیتی کودکی‌شان نیستند. مغز بزرگسالی انعطاف‌پذیر می‌ماند و برای یادگیری تازه گشوده است.\nپژوهش‌های بلندمدت نشان می‌دهند منش با گذر زمان پخته می‌شود. مطالعات حاکی‌اند افراد مسن‌تر کم‌کم کارمندانی وظیفه‌شناس‌تر می‌شوند. آدم‌ها با بالا رفتن سن معمولاً بسیار سازگارتر می‌شوند. ثبات هیجانی نیز در سال‌های بلوغ به‌طور چشمگیری بهتر می‌شود. تعهدات کاری به افراد کمک می‌کند خودانضباطی روزانهٔ محکمی بسازند. مسئولیت‌های خانوادگی بزرگسالان را شنونده‌هایی صبورتر بار می‌آورد. میانسالی خردی ارزشمند و خودمهارگری هیجانی بیشتری به ارمغان می‌آورد.\nهر کس می‌تواند عادت‌های رفتاری تازه را آگاهانه تمرین و پرورش دهد. فردی نامنظم می‌تواند سامانه‌های روزانهٔ بهتری یاد بگیرد و به کار ببندد. کارمندی بی‌حوصله می‌تواند هر روز شنیدنِ آرام و با دقت را تمرین کند. کنش‌های کوچک روزانه در گذر زمان به بهبودهای بزرگی در منش می‌انجامد. تلاش آگاهانهٔ هرروزه به آدم‌ها کمک می‌کند بر عادت‌های منفی‌شان غلبه کنند. رشد شخصی نظم و تمرکز ذهنی پایدار می‌طلبد. هر کس می‌تواند پرورش ویژگی‌های مثبت تازه را برای خود برگزیند.\nسازمان‌ها وقتی کارکنان خودآگاهی قوی پیدا می‌کنند سود فراوان می‌برند. کسانی که خود را می‌شناسند مؤثرتر با همکاران تعامل می‌کنند. تعارض‌های محیط کار را با آرامش و صبر بیشتری مدیریت می‌کنند. در نتیجه تیم‌ها بسیار پربازده‌تر و حمایت‌گرتر می‌شوند. احترام به سبک‌های متنوع شخصیت، روحیهٔ کلی تیم را بالا می‌برد. ارتباط مثبت در محیط کار فضایی سالم می‌سازد. شرکت‌ها وقتی به نقاط قوت شخصیتی گوناگون کارکنان ارزش بدهند موفق می‌شوند.\nدر جمع‌بندی، شخصیت انسان حالتی ثابت و همیشگی نیست. منش ما در تمام زندگی بزرگسالی به تحول ادامه می‌دهد. پژوهش‌های علمی ثابت کرده‌اند بزرگسالان می‌توانند عادت‌هایشان را آگاهانه شکل دهند. خودآگاهی به ما امکان می‌دهد هر روز تغییرهای مثبتی در خود بسازیم. با گذر زمان و پشتکار، هر کس می‌تواند به رشدی معنادار دست یابد.", "glossary": {}, "hl": [], "gist": {"q": "What is the main idea of this article?", "o": ["Why companies should fire introverted employees.", "How personality testing works and why adult character can change through neuroplasticity.", "How to cheat on the Myers-Briggs personality assessment.", "Why childhood habits determine your salary forever."], "a": 1}, "detailed": [{"q": "Why do some psychologists criticize popular personality tests like the Myers-Briggs test?", "o": ["Because the tests cost too much money for small companies.", "Because human nature is complex and test results can change over time.", "Because introverts refuse to take written tests online.", "Because the test was created over three hundred years ago."], "a": 1, "ex": "Paragraph 3 explains that critics question personality tests because human nature is complex, people behave differently in different environments, and test results can change."}, {"q": "What is neuroplasticity according to the fourth paragraph?", "o": ["A mental illness caused by working too hard.", "The brain's ability to form new neural connections and change during adult life.", "A personality test used to measure worker productivity.", "A physical exercise designed to improve sleep quality."], "a": 1, "ex": "Paragraph 4 defines neuroplasticity as the biological process where the adult brain forms new neural connections and reshapes behavior patterns."}, {"q": "How does human personality typically mature as adults age?", "o": ["Adults become more disorganized and impatient.", "People become more conscientious, agreeable, and emotionally stable over time.", "Adults lose their ability to learn new behavioral habits.", "Individuals become very selfish and arrogant."], "a": 1}]}, {"title": "Text 2: Introversion, Extraversion, and Modern Leadership", "topic": "Introversion, Extraversion, and Modern Leadership", "text": "Western business culture has favored outgoing and extraverted personalities for decades. Charismatic leaders often receive quick promotions in corporate environments. Open-plan offices were designed to encourage active group conversations. Team brainstorming sessions reward workers who speak up quickly. Aggressive networking events also benefit outgoing and expressive professionals. Extraverts feel energized when surrounded by large crowds of people. They express their ideas with high energy and passion. Consequently, extraverted workers often dominate office meetings and discussions. Many business schools traditionally trained students to act extraverted.\n\nConversely, introverted employees are frequently misunderstood in modern offices. Introverted individuals are usually quiet, reflective, and pretty reserved. Managers sometimes mischaracterize quiet workers as unfriendly or lacking ambition. However, shyness and introversion are entirely different character traits. Shy people feel anxious during normal social interactions with strangers. Introverts simply prefer quiet environments to process new thoughts. They recharge their personal energy by spending time alone. Quiet reflection allows them to analyze problems deeply before speaking.\n\nRecent organizational psychology research reveals surprising facts about introverted leaders. Introverted managers are incredibly effective at leading proactive teams. Extraverted leaders sometimes interrupt employees and push their own ideas. In contrast, introverted leaders listen carefully to suggestions from staff. They absorb feedback thoroughly before making major business decisions. They allow talented employees to run with creative new initiatives. This quiet support fosters strong team autonomy and trust. Employees feel empowered when their leaders listen attentively to them.\n\nModern workplaces require deep focus and complex analytical skills daily. Introverted professionals excel at tasks that demand sustained mental focus. They write detailed reports and analyze financial numbers very carefully. They do not get distracted easily by noisy office environments. Their methodical approach reduces costly administrative errors in business projects. They complete challenging tasks without needing constant public praise. Their quiet dedication ensures high operational quality across departments. They take great pride in delivering accurate and reliable work.\n\nForcing introverts to act like extraverts is completely counterproductive. Mandatory social events can cause severe exhaustion for quiet workers. Constant group meetings prevent introverts from doing deep work. Companies waste valuable talent when they ignore quiet professionals. Smart managers design quiet spaces for focused individual work. They offer different ways for staff to share their ideas. Written feedback allows introverts to contribute without high stress. Inclusive managers help every employee thrive in their own way.\n\nPsychologists measure personality using the Big Five personality framework. This model evaluates extraversion alongside four other key traits. These traits include conscientiousness, agreeableness, openness, and emotional stability. High conscientiousness predicts strong workplace performance and personal reliability. High agreeableness fosters warm cooperation among team members daily. Openness to experience encourages creative problem solving in organizations. Successful teams require a healthy balance of different personality traits.\n\nResilient organizations need both extraverted and introverted professionals to thrive. Outgoing extraverts excel at public presentation and client sales negotiations. They build exciting networks and attract new business opportunities quickly. Down-to-earth introverts ensure operational stability and careful quality control. Combining these different strengths creates a highly balanced workforce. Mutual respect between different personality types improves overall productivity. Every worker brings unique value to the shared corporate mission. Diversity of character drives innovation across modern global companies.\n\nIn conclusion, introversion is a powerful asset in modern business. Quiet leaders and focused workers bring essential strengths to teams. Companies must value both quiet focus and charismatic energy. Embracing diverse personality types leads to sustainable long-term success. Understanding personality differences builds stronger and happier workplaces.", /* TODO(fa-review) */ "translationFa": "فرهنگ کسب‌وکار غربی دهه‌هاست شخصیت‌های برون‌گرا و اجتماعی را ترجیح داده است. رهبران کاریزماتیک در فضای شرکت‌ها زود ارتقا می‌گیرند. دفترهای دیوارباز برای پررنگ شدن گفت‌وگوهای گروهی طراحی شده‌اند. نشست‌های ایده‌پردازی گروهی به کارمندانی پاداش می‌دهند که بی‌درنگ اظهارنظر می‌کنند. رویدادهای پرتحرک شبکه‌سازی هم به حرفه‌ای‌های اجتماعی و پرانرژی سود می‌رساند. برون‌گرایان در میان جمعیت زیاد انرژی می‌گیرند و ایده‌هایشان را با شور و حرارت بیان می‌کنند. در نتیجه کارکنان برون‌گرا اغلب در جلسات و بحث‌های اداری حرف اول را می‌زنند. بسیاری از مدرسه‌های کسب‌وکار هم به سنت، دانشجویان را به رفتار برون‌گرایانه آموزش می‌دادند.\nدر مقابل، کارکنان درون‌گرا در اداره‌های امروزی اغلب بد فهمیده می‌شوند. درون‌گرایان معمولاً آرام، تأمل‌گر و کم‌حرف‌اند. مدیران گاهی کارکنان کم‌حرف را بی‌دوست یا کم‌انگیزه می‌پندارند. اما خجالت و درون‌گرایی دو ویژگی شخصیتی کاملاً متفاوت‌اند. آدم‌های خجالتی در معاشرت‌های معمولی با غریبه‌ها اضطراب می‌گیرند. درون‌گرایان صرفاً محیط آرام را برای پردازش اندیشه‌های تازه ترجیح می‌دهند. انرژی‌شان را با تنهایی بازیابی می‌کنند. تأملِ آرام به آن‌ها امکان می‌دهد پیش از حرف زدن، مسئله را عمیق واکاوی کنند.\nپژوهش‌های نوین روان‌شناسی سازمانی واقعیت‌های شگفت‌انگیزی دربارهٔ رهبران درون‌گرا آشکار کرده است. مدیران درون‌گرا در رهبری تیم‌های پیش‌قدم فوق‌العاده موفق‌اند. رهبران برون‌گرا گاه حرف کارکنان را می‌برند و ایده‌های خودشان را پیش می‌کشند. در نقطهٔ مقابل، رهبران درون‌گرا با دقت به پیشنهادهای کارکنان گوش می‌دهند. بازخوردها را پیش از تصمیم‌های بزرگ تجاری کامل جذب می‌کنند. اجازه می‌دهند کارکنان بااستعداد ایده‌های خلاقانه را خودشان پیش ببرند. این پشتیبانی بی‌سر‌و‌صدا، استقلال و اعتماد تیمی را نیرومند می‌کند. کارکنان وقتی رهبرشان با دقت به حرفشان گوش می‌دهد احساس ارزشمندی می‌کنند.\nمحیط‌های کاری امروزی هر روز به تمرکز عمیق و مهارت‌های تحلیلی پیچیده نیاز دارند. حرفه‌ای‌های درون‌گرا در کارهایی که تمرکز ذهنی پایدار می‌خواهد درخشش دارند. گزارش‌های مفصل می‌نویسند و اعداد مالی را به‌دقت واکاوی می‌کنند. محیط‌های شلوغ اداری به‌سادگی حواسشان را پرت نمی‌کند. رویهٔ منظمشان خطاهای پرهزینهٔ اداری را در پروژه‌ها کم می‌کند. کارهای سخت را بی‌آنکه تشویق همگانی مدام بخواهند به سرانجام می‌رسانند. فداکاری آرامشان کیفیت بالای کار را در همهٔ بخش‌ها تضمین می‌کند. از ارائهٔ کاری دقیق و قابل‌اعتماد احساس غرور می‌کنند.\nوادار کردن درون‌گرایان به رفتار برون‌گرایانه کاملاً نتیجهٔ معکوس دارد. برنامه‌های اجتماعی اجباری کارکنان کم‌حرف را به‌شدت فرسوده می‌کند. جلسات پی‌درپی گروهی مانع کار عمیق درون‌گرایان می‌شود. شرکت‌ها وقتی از حرفه‌ای‌های کم‌حرف چشم‌پوشی می‌کنند استعداد ارزشمند را هدر می‌دهند. مدیران خردمند برای کار فردیِ متمرکز فضاهای آرامی طراحی می‌کنند. راه‌های گوناگونی برای بیان ایده‌ها در اختیار کارکنان می‌گذارند. بازخورد کتبی به درون‌گرایان امکان می‌دهد بی‌استرس مشارکت کنند. مدیران فراگیر به هر کارمند کمک می‌کنند به شیوهٔ خودش شکوفا شود.\nروان‌شناسان شخصیت را با چارچوب «پنج عامل بزرگ» می‌سنجند. این مدل برون‌گرایی را در کنار چهار ویژگی کلیدی دیگر ارزیابی می‌کند. این ویژگی‌ها وظیفه‌شناسی، سازگاری، گشودگی به تجربه و ثبات هیجانی‌اند. وظیفه‌شناسی بالا پیش‌بینی‌کنندهٔ عملکرد کاری قوی و قابل‌اعتماد بودن فرد است. سازگاری بالا همکاری گرم اعضای تیم را هر روز پربارتر می‌کند. گشودگی به تجربه حل خلاقانهٔ مسئله را در سازمان‌ها تشویق می‌کند. تیم‌های موفق به توازن سالمی از ویژگی‌های شخصیتی گوناگون نیاز دارند.\nسازمان‌های تاب‌آور برای شکوفایی به هم حرفه‌ای‌های برون‌گرا و هم درون‌گرا نیاز دارند. برون‌گرایان اجتماعی در ارائهٔ عمومی و مذاکرهٔ فروش با مشتریان عالی‌اند. شبکه‌های پرجوش‌وخروش می‌سازند و فرصت‌های کاری تازه را زود جذب می‌کنند. درون‌گرایان خاک‌نشین ثبات عملیاتی و کنترل کیفیت دقیق را تضمین می‌کنند. ترکیب این توانمندی‌های متفاوت، نیروی کاری به‌شدت متوازنی می‌سازد. احترام متقابل میان تیپ‌های مختلف شخصیت بهره‌وری کلی را بالا می‌برد. هر کارمند ارزشی یکتا به مأموریت مشترک شرکت می‌آورد. تنوع منش، نوآوری را در شرکت‌های امروزی جهان پیش می‌برد.\nدر جمع‌بندی، درون‌گرایی سرمایه‌ای ارزشمند در کسب‌وکار امروزی است. رهبران کم‌حرف و کارکنان متمرکز نقاط قوت اساسی‌ای به تیم می‌آورند. شرکت‌ها باید هم به تمرکز آرام و هم به انرژی کاریزماتیک ارزش بگذارند. پذیرفتن تیپ‌های متنوع شخصیت به موفقیت پایدار بلندمدت می‌انجامد. فهم تفاوت‌های شخصیتی، محیط‌های کاری محکم‌تر و شادتری می‌سازد.", "glossary": {}, "hl": [], "gist": {"q": "What is the primary focus of this article?", "o": ["Why companies should eliminate all extraverted managers.", "The value of both introverted and extraverted traits in leadership and modern business.", "How to organize large corporate parties.", "The history of open-plan office furniture."], "a": 1}, "detailed": [{"q": "What is the fundamental difference between shyness and introversion described in paragraph 2?", "o": ["Shy people hate music, while introverts love classical music.", "Shyness involves anxiety in social situations, while introversion is simply a preference for quiet environments to process thoughts.", "Introverts are always disorganized, while shy people are extremely reliable.", "Shyness only affects children, while introversion only affects adults."], "a": 1, "ex": "Paragraph 2 clarifies that shy people feel anxious in social interactions, whereas introverts simply prefer quiet environments to recharge and process thoughts."}, {"q": "Why are introverted leaders particularly effective when managing proactive teams?", "o": ["Because they yell at workers who make mistakes.", "Because they listen carefully to feedback and allow talented staff to run with new ideas.", "Because they force everyone to work late every evening.", "Because they refuse to attend team meetings."], "a": 1, "ex": "Paragraph 3 explains that introverted leaders listen carefully to suggestions and allow proactive employees to execute creative initiatives without interference."}, {"q": "How can smart managers help introverted employees contribute effectively in the workplace?", "o": ["By forcing them to give public speeches every day.", "By providing quiet workspaces and offering options like written feedback.", "By ignoring their work completely.", "By banning smartphones from the building."], "a": 1}]}];
LESSONS["1B"].writing={"prompts": [{"title": "Prompt 1", "text": "Write a short personal profile (100–150 words) describing a colleague, friend, or relative whom you deeply respect. Detail their major character strengths and minor behavioral flaws using at least four degree adverbs (incredibly, extremely, fairly, pretty, totally), two prefixed adjectives (impatient, inconsiderate, unreliable, disorganized), and two character expressions from Section 1 (level-headed, heart of gold, speak one's mind, stand up for).", "sample": "I would like to describe my senior colleague, Farhad, whom I truly admire. He is an incredibly level-headed project lead who manages complex engineering assignments with impressive calm. He is extremely generous with his time and genuinely has a heart of gold, as he is always ready to assist junior staff.\nHe is completely honest in his communications and never hesitates to speak his mind during strategy meetings. On occasion, he can be fairly disorganized with his administrative paperwork, and he gets a bit impatient when software tools operate slowly. However, he is never inconsiderate at all, and his overall leadership is absolutely wonderful. He is a totally reliable professional whom everyone on our team can depend on."}, {"title": "Prompt 2", "text": "Write a paragraph (100–150 words) reflecting on your own personality traits. Discuss one character strength you are proud of and one habit or trait you would like to improve. You must use at least four degree adverbs (extremely, incredibly, pretty, fairly, absolutely), two prefixed adjectives (impatient, disorganized, inconsiderate, impolite), and correct adjective-adverb structures."}]};
LESSONS["1B"].pretest=[{"q": "Winning is very important to you.", "o": ["competitive", "easygoing", "reliable", "disorganized"], "a": 0, "ex": ""}, {"q": "You're relaxed about life.", "o": ["easygoing", "competitive", "arrogant", "dishonest"], "a": 0, "ex": ""}, {"q": "You handle small problems well.", "o": ["easygoing", "unreliable", "selfish", "inconsiderate"], "a": 0, "ex": ""}, {"q": "You never cheat or steal.", "o": ["honest", "dishonest", "arrogant", "disorganized"], "a": 0, "ex": ""}, {"q": "People can always count on you.", "o": ["reliable", "unreliable", "disorganized", "unfriendly"], "a": 0, "ex": ""}, {"q": "You're not well organized.", "o": ["disorganized", "reliable", "generous", "honest"], "a": 0, "ex": ""}, {"q": "You don't get along with people.", "o": ["unfriendly", "generous", "easygoing", "reliable"], "a": 0, "ex": ""}, {"q": "You can do a lot of things well.", "o": ["talented", "dishonest", "disorganized", "impatient"], "a": 0, "ex": ""}, {"q": "You like to have fun with people.", "o": ["have a great sense of humor", "arrogant", "unfriendly", "inconsiderate"], "a": 0, "ex": ""}, {"q": "You think you're the best.", "o": ["arrogant", "humble", "generous", "down-to-earth"], "a": 0, "ex": ""}, {"q": "You're not relaxed around people.", "o": ["shy", "outgoing", "generous", "competitive"], "a": 0, "ex": ""}, {"q": "You give a lot of your time or money.", "o": ["generous", "selfish", "arrogant", "dishonest"], "a": 0, "ex": ""}];
LESSONS["1B"].grammar.bookExA=[{"q": "My uncle is _____ laid-back — nothing ever bothers him.", "o": ["totally", "not"], "a": 0, "ex": "totally = کاملاً."}, {"q": "She's _____ generous — always buying little gifts for people.", "o": ["pretty", "not at all"], "a": 0, "ex": "pretty = تا حدی."}, {"q": "He was _____ honest with me about the mistake.", "o": ["very", "not very"], "a": 0, "ex": "very برای تأکید معمولی به کار می‌رود."}, {"q": "The view from the summit was _____ wonderful.", "o": ["absolutely", "fairly"], "a": 0, "ex": "wonderful صفت مطلق است؛ absolutely درست است."}, {"q": "He's not competitive _____; he doesn't even care who wins.", "o": ["at all", "completely"], "a": 0, "ex": "at all بعد از منفی می‌آید."}, {"q": "She gets _____ impatient in long lines.", "o": ["incredibly", "pretty much"], "a": 0, "ex": "incredibly قبل از صفت می‌آید."}, {"q": "My notes are _____ disorganized this week.", "o": ["fairly", "totally not"], "a": 0, "ex": "fairly = تا حدی."}, {"q": "He's _____ reliable — you can always count on him.", "o": ["completely", "fairly"], "a": 0, "ex": "completely = کاملاً."}, {"q": "She's an _____ talented painter.", "o": ["extremely", "extreme"], "a": 0, "ex": "قبل از صفت باید قید بیاید."}, {"q": "That comment was _____ inconsiderate.", "o": ["really", "real"], "a": 0, "ex": "قبل از صفت باید قید بیاید."}];
