LESSONS["1B"].grammar.extraQuiz1=[{"q": "He's _____ generous with his time.", "o": ["extremely", "extreme"], "a": 0, "ex": ""}, {"q": "She's _____ easygoing about small mistakes.", "o": ["pretty", "absolutely"], "a": 0, "ex": ""}, {"q": "Her cooking is _____ amazing.", "o": ["absolutely", "very"], "a": 0, "ex": ""}, {"q": "He's not selfish _____.", "o": ["at all", "completely"], "a": 0, "ex": ""}, {"q": "They're _____ reliable business partners.", "o": ["totally", "fairly a bit"], "a": 0, "ex": ""}, {"q": "My brother is _____ laid-back about deadlines.", "o": ["fairly", "totally not"], "a": 0, "ex": ""}, {"q": "The opposite of \"friendly\" is _____.", "o": ["unfriendly", "disfriendly"], "a": 0, "ex": ""}, {"q": "The opposite of \"honest\" is _____.", "o": ["dishonest", "unhonest"], "a": 0, "ex": ""}, {"q": "She's _____ talented at the piano.", "o": ["incredibly", "incredible"], "a": 0, "ex": ""}, {"q": "He's a _____ cool guy, very down-to-earth.", "o": ["pretty", "pretty much a"], "a": 0, "ex": ""}];
LESSONS["1B"].grammar.extraQuiz2=[{"q": "The opposite of \"organized\" is _____.", "o": ["disorganized", "inorganized"], "a": 0, "ex": ""}, {"q": "The opposite of \"patient\" is _____.", "o": ["impatient", "unpatient"], "a": 0, "ex": ""}, {"q": "The opposite of \"reliable\" is _____.", "o": ["unreliable", "disreliable"], "a": 0, "ex": ""}, {"q": "She's not arrogant _____ — she's actually very humble.", "o": ["at all", "totally"], "a": 0, "ex": ""}, {"q": "He's _____ honest about his opinions.", "o": ["completely", "fairly not"], "a": 0, "ex": ""}, {"q": "Their new manager is _____ competitive.", "o": ["extremely", "extreme"], "a": 0, "ex": ""}, {"q": "She's _____ disorganized, but she always finishes on time.", "o": ["pretty", "absolutely"], "a": 0, "ex": ""}, {"q": "That was an _____ generous thing to do.", "o": ["incredibly", "incredible"], "a": 0, "ex": ""}, {"q": "He's _____ reliable — I trust him completely.", "o": ["totally", "fairly a bit"], "a": 0, "ex": ""}, {"q": "The opposite of \"considerate\" is _____.", "o": ["inconsiderate", "disconsiderate"], "a": 0, "ex": ""}];
LESSONS["1B"].convo1=[{"q": "Who's someone you really admire, and why?", "sample": "Honestly, I'd have to say my older sister. She's incredibly hard-working — like, she'll stay up late finishing something just to make sure it's done right. And she's extremely reliable too, which I really admire; if she says she'll do something, she just does it, no excuses. She can be pretty disorganized sometimes, honestly — she forgets stuff all the time, loses her keys, that kind of thing — but she's completely honest, so you always know exactly where you stand with her. And even though she's really talented at her job and could easily brag about it, she's not arrogant at all. I think that combination is pretty rare, actually.", "glossary": {}, "hl": ["incredibly", "extremely", "reliable", "pretty", "disorganized", "completely", "honest", "arrogant", "talented"]}];
LESSONS["1B"].convo2=[{"q": "Tell me about a friend or coworker who's really easy to get along with.", "sample": "Yeah, so, my coworker Sam is probably the first person who comes to mind. He's fairly easygoing — like, nothing really seems to stress him out, even when deadlines are tight. He's very down-to-earth too, so whenever I bring him a problem, he doesn't overreact, he just gives me really practical advice and helps me figure it out. He's not pushy or competitive at all either, which makes him easy to work with. And honestly, he's totally reliable — if he says he'll help with something, he actually does it, every time. We just get along really well, and I think a lot of that comes from him being so easygoing.", "glossary": {}, "hl": ["fairly", "easygoing", "down-to-earth", "competitive", "totally", "reliable"]}];
LESSONS["1B"].sessions=[{"id": "cb1", "stage": "Coursebook", "icon": "💬", "title": "Who Do You Admire?", "fa": "متن: چه کسی را تحسین می‌کنید؟", "parts": [{"t": "context", "label": "Context", "title": "Who Is Someone You Really Admire?", "lines": [{"sp": "Jessica Davis", "text": "My English teacher. She's incredibly talented and creative. And she has a great sense of humor. She's pretty disorganized, though. She forgets something almost every class, but her classes are absolutely wonderful!"}, {"sp": "Mike Kowalski", "text": "I really admire a guy in my karate class. He's extremely competitive, but when he wins, he's not arrogant like some of the other guys. He's not very outgoing, so some people think he's unfriendly, but I think he's basically just shy."}, {"sp": "Bryan Yuen", "text": "I think my dad's a pretty cool guy. We get along really well. He's fairly easygoing and laid-back. And he's very practical and down-to-earth, so he always gives me good advice. Also, he's completely honest with me. I can trust what he says."}, {"sp": "Emilia Perez", "text": "My friend Luisa. She's so helpful and generous. I mean, she's always doing things for other people. She's not selfish at all. And she's totally reliable. If she says she'll help you with something, she does. You can always count on her."}]}]}, {"id": "cb2", "stage": "Coursebook", "icon": "⭕", "title": "Pre-test", "fa": "پیش‌آزمون", "parts": [{"t": "selfcheck", "key": "pretest", "label": "Pre-test"}]}, {"id": "cb3", "stage": "Coursebook", "icon": "📝", "title": "Degree Adverbs", "fa": "آموزش: قیدهای شدت و پیشوندها", "parts": [{"t": "teach", "pts": [0, 1, 2, 3, 4]}]}, {"id": "cb4", "stage": "Coursebook", "icon": "✅", "title": "Exercise", "fa": "تمرین کتاب", "parts": [{"t": "bookExercise", "key": "bookExA", "label": "Exercise"}]}, {"id": "cb5", "stage": "Coursebook", "icon": "🔁", "title": "Building Vocabulary", "fa": "تقویت واژگان", "parts": [{"t": "bookExercise", "key": "buildingVocab", "label": "Building Vocabulary"}]}, {"id": "ex1", "stage": "Extra", "icon": "📚", "title": "Vocabulary 1", "fa": "لغات ۱", "parts": [{"t": "vocab", "from": 0, "to": 10}, {"t": "matching", "sets": [1, 2]}]}, {"id": "ex2", "stage": "Extra", "icon": "📚", "title": "Vocabulary 2", "fa": "لغات ۲", "parts": [{"t": "vocab", "from": 10, "to": 20}, {"t": "matching", "sets": [3, 4]}, {"t": "gap"}]}, {"id": "ex3", "stage": "Extra", "icon": "🎯", "title": "Grammar Quiz 1", "fa": "آزمون گرامر ۱", "parts": [{"t": "quizset", "key": "extraQuiz1", "label": "Grammar Quiz 1"}]}, {"id": "ex4", "stage": "Extra", "icon": "🎯", "title": "Grammar Quiz 2", "fa": "آزمون گرامر ۲", "parts": [{"t": "quizset", "key": "extraQuiz2", "label": "Grammar Quiz 2"}]}, {"id": "ex5", "stage": "Extra", "icon": "🗣️", "title": "Conversation Practice 1", "fa": "تمرین مکالمه ۱", "parts": [{"t": "convo", "key": "convo1"}]}, {"id": "ex6", "stage": "Extra", "icon": "🗣️", "title": "Conversation Practice 2", "fa": "تمرین مکالمه ۲", "parts": [{"t": "convo", "key": "convo2"}]}, {"id": "ex7", "stage": "Extra", "icon": "📖", "title": "Article 1", "fa": "مقاله ۱", "parts": [{"t": "reading", "text": 0}]}, {"id": "ex8", "stage": "Extra", "icon": "📖", "title": "Article 2", "fa": "مقاله ۲", "parts": [{"t": "reading", "text": 1}]}, {"id": "ex9", "stage": "Extra", "icon": "✍️", "title": "Writing", "fa": "نوشتن", "parts": [{"t": "writing"}]}];

