LESSONS["1C"].vocab=[{/* TODO(fa-review) */ "en":"drive someone crazy","type":"idiom","fa":"دیوانه کردن / کلافه کردن کسی","ex":"His constant pen-clicking during meetings is starting to drive me crazy.","collocations":[{"en":"drive someone up the wall","fa":"کفری کردن کسی"},{"en":"constantly annoying","fa":"همیشه آزاردهنده"}],"chunks":[{"en":"get on someone's nerves","fa":"اعصاب کسی را خرد کردن"},{"en":"it drives me mad","fa":"دیوانه‌ام می‌کند"}]},{/* TODO(fa-review) */ "en":"bring up an issue","type":"chunk","fa":"مطرح کردن یک موضوع یا مشکل","ex":"It is usually best to bring up an issue privately rather than in front of the whole team.","collocations":[{"en":"raise a concern","fa":"نگرانی را مطرح کردن"},{"en":"discuss the problem","fa":"مشکل را بحث کردن"}],"chunks":[{"en":"talk it over","fa":"درباره‌اش صحبت کردن"},{"en":"in a private conversation","fa":"در گفتگوی خصوصی"}]},{/* TODO(fa-review) */ "en":"clear the air","type":"idiom","fa":"برطرف کردن سوءتفاهم‌ها و کدورت‌ها","ex":"We had an open discussion yesterday to clear the air after our disagreement.","collocations":[{"en":"clear up a misunderstanding","fa":"سوءتفاهم را رفع کردن"},{"en":"resolve the conflict","fa":"تعارض را حل کردن"}],"chunks":[{"en":"have an honest talk","fa":"صادقانه صحبت کردن"},{"en":"start fresh","fa":"از نو شروع کردن"}]},{/* TODO(fa-review) */ "en":"a minor irritation","type":"chunk","fa":"یک ناراحتی یا آزار کوچک","ex":"Leaving cabinet doors open is a minor irritation, but doing it daily gets annoying.","collocations":[{"en":"a small annoyance","fa":"آزار کوچک"},{"en":"a pet peeve","fa":"آزار مخصوص و شخصی"}],"chunks":[{"en":"no big deal","fa":"مهم نبودن"},{"en":"it adds up","fa":"کم‌کم جمع می‌شود"}]},{/* TODO(fa-review) */ "en":"diplomatic approach","type":"collocation","fa":"رویکرد دیپلماتیک و با سیاست","ex":"Taking a diplomatic approach helps resolve office conflicts without hurting feelings.","collocations":[{"en":"a tactful reply","fa":"پاسخ باملاحظه"},{"en":"handle a conflict","fa":"تعارض را مدیریت کردن"}],"chunks":[{"en":"choose your words carefully","fa":"کلمات را با دقت انتخاب کردن"},{"en":"avoid hurting feelings","fa":"آسیب رساندن به احساسات را اجتناب کردن"}]},{/* TODO(fa-review) */ "en":"accumulate over time","type":"chunk","fa":"به مرور زمان انباشته شدن","ex":"Unaddressed habit irritations tend to accumulate over time into major arguments.","collocations":[{"en":"build up gradually","fa":"تدریجی جمع شدن"},{"en":"grow worse","fa":"بدتر شدن"}],"chunks":[{"en":"little by little","fa":"کم‌کم و قدم‌به‌قدم"},{"en":"in the long run","fa":"در بلندمدت"}]},{/* TODO(fa-review) */ "en":"cognitive reframing","type":"collocation","fa":"بازسازی شناختی (تغییر زاویه دید)","ex":"Practicing cognitive reframing allows you to view a colleague's quirks with more patience.","collocations":[{"en":"change your perspective","fa":"زاویه دید را عوض کردن"},{"en":"look at it differently","fa":"از زاویه دیگر نگاه کردن"}],"chunks":[{"en":"see the bigger picture","fa":"تصویر بزرگ را دیدن"},{"en":"give someone the benefit of the doubt","fa":"به کسی حسن ظن داشتن"}]},{/* TODO(fa-review) */ "en":"stand up for yourself","type":"chunk","fa":"از حق خود دفاع کردن","ex":"You need to stand up for yourself politely when a coworker takes credit for your work.","collocations":[{"en":"assert yourself","fa":"قاطع و صاحب‌نظر بودن"},{"en":"express disagreement","fa":"اختلاف نظر را بیان کردن"}],"chunks":[{"en":"say no politely","fa":"محترمانه نه گفتن"},{"en":"know your rights","fa":"حقوق خود را دانستن"}]},{/* TODO(fa-review) */ "en":"disrupt team productivity","type":"chunk","fa":"اختلال در بازدهی تیم","ex":"Loud personal phone calls in an open office disrupt team productivity significantly.","collocations":[{"en":"reduce efficiency","fa":"بازدهی را کاهش دادن"},{"en":"waste time","fa":"وقت تلف کردن"}],"chunks":[{"en":"stay focused","fa":"متمرکز ماندن"},{"en":"get things done","fa":"کارها را پیش بردن"}]},{/* TODO(fa-review) */ "en":"tolerable behavior","type":"collocation","fa":"رفتار قابل تحمل","ex":"We need to distinguish between intolerable actions and simple, tolerable behavior.","collocations":[{"en":"unacceptable behavior","fa":"رفتار غیرقابل قبول"},{"en":"draw the line","fa":"مرز قائل شدن"}],"chunks":[{"en":"put up with something","fa":"تحمل کردن چیزی"},{"en":"cross the line","fa":"از مرز گذشتن"}]},{/* TODO(fa-review) */ "en":"workplace etiquette","type":"collocation","fa":"آداب و قوانین رفتار در محیط کار","ex":"Following basic workplace etiquette creates a comfortable environment for everyone.","collocations":[{"en":"office rules","fa":"قوانین محیط کار"},{"en":"professional behavior","fa":"رفتار حرفه‌ای"}],"chunks":[{"en":"common courtesy","fa":"ادب رایج"},{"en":"respect shared space","fa":"فضای مشترک را محترم شمردن"}]},{/* TODO(fa-review) */ "en":"take something personally","type":"idiom","fa":"چیزی را به خود گرفتن / شخصی تلقی کردن","ex":"Try not to take her sharp tone personally; she is under a lot of deadline pressure.","collocations":[{"en":"feel offended","fa":"برآشفته شدن"},{"en":"feel hurt","fa":"آزرده شدن"}],"chunks":[{"en":"don't take it the wrong way","fa":"بد برداشت نکردن"},{"en":"it is not about you","fa":"مربوط به تو نیست"}]},{/* TODO(fa-review) */ "en":"address a colleague","type":"collocation","fa":"مخاطب قرار دادن / صحبت کردن با همکار","ex":"It is important to address a colleague respectfully when pointing out a mistake.","collocations":[{"en":"talk to a coworker","fa":"با همکار صحبت کردن"},{"en":"speak respectfully","fa":"با احترام صحبت کردن"}],"chunks":[{"en":"have a word with someone","fa":"با کسی صحبت کوتاه کردن"},{"en":"in a calm manner","fa":"به‌آرامی و خونسردی"}]},{/* TODO(fa-review) */ "en":"smooth things over","type":"idiom","fa":"آرام کردن اوضاع / حل و فصل کردن ارام مشکلات","ex":"He bought coffee for the team to smooth things over after arriving late to the presentation.","collocations":[{"en":"ease the tension","fa":"تنش را کم کردن"},{"en":"patch up a relationship","fa":"رابطه را ترمیم کردن"}],"chunks":[{"en":"let it go","fa":"ول کردن ماجرا"},{"en":"move on","fa":"گذشتن از ماجرا"}]},{/* TODO(fa-review) */ "en":"mutual understanding","type":"collocation","fa":"درک متقابل","ex":"Building mutual understanding makes it easier to handle personal differences at work.","collocations":[{"en":"build trust","fa":"اعتماد ساختن"},{"en":"shared expectations","fa":"انتظارات مشترک"}],"chunks":[{"en":"see both sides","fa":"هر دو طرف را دیدن"},{"en":"find common ground","fa":"زمین مشترک پیدا کردن"}]},{/* TODO(fa-review) */ "en":"lose your cool","type":"idiom","fa":"از کوره در رفتن / کنترل خود را از دست دادن","ex":"Even when a coworker interrupts you repeatedly, try not to lose your cool.","collocations":[{"en":"control your temper","fa":"خشم خود را کنترل کردن"},{"en":"stay composed","fa":"خونسرد ماندن"}],"chunks":[{"en":"take a deep breath","fa":"نفس عمیق کشیدن"},{"en":"count to ten","fa":"تا ده شمردن"}]},{/* TODO(fa-review) */ "en":"set clear boundaries","type":"chunk","fa":"تعیین مرزهای مشخص","ex":"Setting clear boundaries early prevents colleagues from overloading you with extra tasks.","collocations":[{"en":"define limits","fa":"حدود را مشخص کردن"},{"en":"protect your time","fa":"از وقت خود محافظت کردن"}],"chunks":[{"en":"say no when needed","fa":"در صورت لزوم نه گفتن"},{"en":"respect others' limits","fa":"حدود دیگران را محترم شمردن"}]},{/* TODO(fa-review) */ "en":"a touchy subject","type":"idiom","fa":"موضوع حساس و دردسرساز","ex":"Punctuality turned out to be a touchy subject during our performance review.","collocations":[{"en":"a sensitive topic","fa":"موضوع حساس"},{"en":"avoid the topic","fa":"از موضوع طفره رفتن"}],"chunks":[{"en":"steer clear of","fa":"دوری کردن از"},{"en":"a sore point","fa":"نقطه حساس و دردناک"}]},{/* TODO(fa-review) */ "en":"foster a positive environment","type":"chunk","fa":"ترویج/ایجاد یک فضای مثبت","ex":"Managers who listen to complaints actively foster a positive environment.","collocations":[{"en":"create a supportive atmosphere","fa":"فضای حمایتی ساختن"},{"en":"encourage teamwork","fa":"کار تیمی را تشویق کردن"}],"chunks":[{"en":"lead by example","fa":"با عمل خود رهبری کردن"},{"en":"boost morale","fa":"روحیه را بالا بردن"}]},{/* TODO(fa-review) */ "en":"bite your tongue","type":"idiom","fa":"جلوی زبان خود را گرفتن / سکوت کردن","ex":"I had to bite my tongue during the meeting to avoid making an angry comment.","collocations":[{"en":"hold back a comment","fa":"حرفی را نگه داشتن"},{"en":"stay silent","fa":"ساکت ماندن"}],"chunks":[{"en":"think before you speak","fa":"قبل از حرف زدن فکر کردن"},{"en":"keep the peace","fa":"آرامش را حفظ کردن"}]}];
LESSONS["1C"].texts=[{"title": "Text 1: Handling Daily Workplace Irritations Diplomatically", "topic": "Handling Daily Workplace Irritations Diplomatically", "text": "In any modern office or shared space, people with different backgrounds, habits, and communication styles must work together every day. While working with different people brings many benefits to a company, sharing a physical or virtual work environment often highlights differences in daily habits. Over time, small habits that seem harmless to one person can become a major source of annoyance for another. Understanding how daily workplace habits affect team results, and learning how to address annoying actions politely, is essential for keeping professional peace and personal happiness.\n\nWorkplace habits that break concentration and slow down daily work are surprisingly common across many companies. For example, colleagues who frequently answer phone calls on speakerphone, leave dirty dishes in the kitchen area, or talk loudly in open offices can create an environment where focus becomes nearly impossible. Similarly, arriving late for group meetings or failing to reply to urgent emails forces team members to change their plans needlessly. When workers face continuous disruptions, their stress levels increase and their overall results drop. What begins as a minor habit annoyance can quickly build up into deep anger if people choose to ignore it for too long.\n\nWhen dealing with a difficult colleague, many workers make the mistake of suffering in silence or reacting with sudden anger. Neither approach solves the main problem. A far more effective strategy involves addressing the behavior politely before emotions become too strong. Choosing the right time and private place for a conversation is critical. Rather than complaining about a colleague in front of other workers, ask for a quiet private discussion. Speak calmly and focus on the specific action itself rather than attacking the person's character. For instance, explaining how loud calls make it hard for you to focus on important reports is much more helpful than calling a colleague rude.\n\nIn addition to direct communication, changing how you think about a situation offers a powerful mental tool for handling actions you cannot fully control. Instead of assuming a colleague's annoying habit is done on purpose, remind yourself that people rarely try to annoy others deliberately. They may simply be unaware of their habit or dealing with personal stress at home. Thinking about the situation differently helps reduce emotional stress, allowing you to react with patience rather than anger.\n\nFinally, self-awareness plays a vital role in keeping good relationships with team members. It is easy to notice irritating habits in others while remaining completely unaware of our own. Taking time to examine your own daily habits in the office can reveal actions that might be annoying to your peers. Asking for honest feedback from trusted colleagues shows maturity and a commitment to good teamwork. Ultimately, creating a peaceful workplace requires effort from everyone. By practicing open communication, emotional control, and mutual respect, workers can solve habit conflicts successfully and build strong working relationships over time. Strong teamwork always begins with clear communication and mutual respect.", /* TODO(fa-review) */ "translationFa": "در هر اداره یا فضای مشترک امروزی، آدم‌هایی با پیشینه‌ها، عادت‌ها و سبک‌های گفتاری متفاوت باید هر روز کنار هم کار کنند. همکاری با آدم‌های متفاوت برای شرکت سودهای فراوانی دارد، اما به اشتراک گذاشتن یک محیط کاری — حضوری یا مجازی — معمولاً تفاوت‌های عادت‌های روزمره را برجسته می‌کند. به مرور، عادت‌های کوچکی که از نگاه یک نفر بی‌ضرر می‌نمایند، می‌توانند برای دیگری منبع آزار بزرگی شوند. فهم اینکه عادت‌های روزانهٔ محیط کار چگونه بر نتیجهٔ تیم اثر می‌گذارد و یادگیری مؤدبانه مطرح کردن کنش‌های آزارنده، برای حفظ آرامش حرفه‌ای و شادی شخصی ضروری است.\nعادت‌های کاری که تمرکز را می‌شکنند و کار روزانه را کند می‌کنند، در شرکت‌های مختلف شگفت‌آور رایج‌اند. مثلاً همکارانی که مدام تماس‌های تلفنی را روی بلندگو جواب می‌دهند، ظرف کثیف در آبدارخانه جا می‌گذارند یا در دفاتر دیوارباز بلند حرف می‌زنند، محیطی می‌سازند که تمرکز تقریباً ناممکن می‌شود. همچنین دیر رسیدن به جلسات گروهی یا بی‌جواب گذاشتن ایمیل‌های فوری، اعضای تیم را ناچار می‌کند بی‌دلیل برنامه‌هایشان را عوض کنند. وقتی کارکنان با اختلال‌های پیاپی روبه‌رو می‌شوند، سطح استرسشان بالا می‌رود و نتیجهٔ کلی‌شان افت می‌کند. آزار کوچکِ یک عادت ساده، اگر طولانی نادیده گرفته شود، به‌سرعت به خشم عمیق بدل می‌شود.\nدر برخورد با همکار دشوار، بسیاری از کارکنان اشتباه می‌کنند: یا در سکوت می‌سوزند یا با خشم ناگهانی واکنش نشان می‌دهند. هیچ‌کدام از این دو راه مسئلهٔ اصلی را حل نمی‌کند. راهبردی بسیار مؤثرتر آن است که پیش از آنکه هیجان‌ها بالا بگیرد، مؤدبانه به رفتار اشاره کنیم. انتخاب زمان و مکان خصوصیِ مناسب برای گفت‌وگو اهمیت حیاتی دارد. به‌جای غر زدن از همکار در حضور بقیه، یک گفت‌وگوی آرام و خصوصی بخواهید. آرام حرف بزنید و بر خودِ کنش مشخص تمرکز کنید، نه حمله به شخصیت آدم‌ها. مثلاً توضیح اینکه تماس‌های بلند چه‌قدر تمرکز روی گزارش‌های مهم را برایتان سخت می‌کند، بسیار سازنده‌تر از آن است که همکار را بی‌ادب بنامید.\nدر کنار گفت‌وگوی مستقیم، تغییر نگاه به موقعیت، ابزاری ذهنی و نیرومند برای مدیریت کنش‌هایی است که برشان تسلط کامل نداریم. به‌جای آنکه فرض کنیم عادت آزارندهٔ همکار عمدی است، به خودتان یادآوری کنید که آدم‌ها به‌ندرت قصد آزار دیگران را دارند. شاید از عادت خودش بی‌خبر باشد یا در خانه درگیر استرس شخصی. متفاوت اندیشیدن دربارهٔ موقعیت، استرس هیجانی را کم می‌کند و به شما اجازه می‌دهد به‌جای خشم، با صبر واکنش نشان دهید.\nسرانجام، خودآگاهی نقشی حیاتی در حفظ رابطهٔ خوب با اعضای تیم دارد. دیدن عادت‌های عصبی‌کنندهٔ دیگران آسان است، اما از عادت‌های خودمان غافلیم. وقت گذاشتن برای وارسی عادت‌های روزانهٔ خود در اداره می‌تواند کنش‌هایی را آشکار کند که شاید برای همکاران آزاردهنده باشند. درخواست بازخورد صادقانه از همکاران مورد اعتماد، نشان‌دهندهٔ بلوغ و تعهد به کار تیمی خوب است. در نهایت، ساختن محیط کاری آرام تلاش همه را می‌طلبد. با تمرین گفت‌وگوی روبه‌رو، مهار هیجان و احترام متقابل، کارکنان می‌توانند تعارض‌های عادتی را با موفقیت حل کنند و با گذر زمان رابطه‌های کاری محکمی بسازند. کار تیمی قوی همیشه از ارتباط روشن و احترام متقابل آغاز می‌شود.", "glossary": {}, "hl": [], "gist": {"q": "What is the primary purpose of the text?", "o": ["To explain why employees should report annoying colleagues to human resources immediately.", "To offer practical strategies for managing workplace habit conflicts through communication and reframing.", "To argue that working from home is superior to working in open shared office spaces.", "To list the most common technical skills required for professional success in modern companies."], "a": 1}, "detailed": [{"q": "What mistake do many workers make when facing a frustrating colleague?", "o": ["They write formal complaints to executive directors.", "They suffer in silence or react with sudden anger.", "They change their working hours without telling anyone.", "They ask for an immediate transfer to a different department."], "a": 1}, {"q": "How does the author suggest framing a discussion about an annoying behavior?", "o": ["Focus on the person's personality traits and past failures.", "Discuss the problem publicly during a team meeting.", "Focus objectively on the specific action and its impact on your work.", "Insist that the colleague apologize before listening to their side."], "a": 2}, {"q": "What benefit does changing how you view a colleague's action provide?", "o": ["It forces the other person to change their behavior automatically.", "It completely eliminates the need for professional teamwork.", "It reduces emotional stress by helping you react with patience.", "It proves to your manager that you are always right."], "a": 2}]}, {"title": "Text 2: Why Small Irritations Accumulate into Major Conflicts", "topic": "Why Small Irritations Accumulate into Major Conflicts", "text": "Human beings are creatures of habit, relying on familiar daily routines to navigate their personal and professional lives. However, when these individual habits clash in shared spaces like offices, schools, or homes, friction is almost inevitable. Small irritations, such as leaving cabinet doors open, constantly interrupting during team discussions, or misplacing shared tools, may seem minor by themselves. Yet, when repeated daily over weeks or months, these small annoyances build up into serious personal conflicts. Understanding why small habit irritations cause such strong reactions is the first step toward managing them effectively and keeping healthy relationships.\n\nThe psychological reason small irritations build up so quickly relates to how the human mind handles stress and personal boundaries. When someone repeatedly does something annoying, the affected person begins to expect the problem before it even happens. This constant state of waiting for a problem creates continuous mild stress, making the person increasingly sensitive to the action. Over time, what was originally a minor distraction feels like a deliberate sign of disrespect. Consequently, a sudden argument may break out over a very small event, surprising the person who caused it because they failed to see how much tension had been growing over time.\n\nTo prevent small irritations from damaging professional or personal relationships, individuals must learn how to address annoying behaviors politely. Timely, honest communication is essential. Waiting until you are completely overwhelmed usually leads to angry statements that make the other person defensive. Instead, bring up the issue early using calm and neutral language. Focus on finding practical solutions rather than demanding complete perfection. For example, if a teammate's messy file system slows down shared projects, suggest a simple, organized system that helps both of you, rather than simply complaining about their messy habits.\n\nWhen dealing with habits that cannot easily be changed, changing your mental focus serves as a very useful strategy. This does not mean ignoring real problems, but rather adjusting your perspective to reduce personal stress. By accepting that everyone has unique habits and occasional annoying traits, you can lower your expectations of complete perfection from others. Reminding yourself of a colleague's positive work helps keep minor habit annoyances in proper balance, preventing brief moments of frustration from ruining your working relationship.\n\nFurthermore, developing strong team relationships requires honest self-awareness. People often judge others by their actions while judging themselves by their good intentions. You might excuse your own habit of arriving late to a meeting because you were busy, yet feel angry when a colleague does the exact same thing. Developing understanding allows you to recognize that your habits might be equally annoying to co-workers or family members. When teams build a culture of mutual understanding and forgiveness, individuals feel comfortable discussing problems openly without fear of harsh judgment. Through active listening, polite discussion, and personal flexibility, people can transform habit conflicts into opportunities for stronger teamwork and personal growth. Taking steps to respect each other's habits leads to long-term success. Learning to accept minor differences helps everyone maintain peace and productiveness.", /* TODO(fa-review) */ "translationFa": "انسان‌ها موجوداتی عادتمندند و برای ادارهٔ زندگی شخصی و حرفه‌ای‌شان به روتین‌های آشنا تکیه می‌کنند. اما وقتی این عادت‌های فردی در فضاهای مشترک مانند اداره، مدرسه یا خانه به هم می‌خورند، اصطکاک تقریباً حتمی است. آزارهای کوچک — مثل باز گذاشتن در کابینت، پشت‌سرهم قطع حرف زدن در بحث‌های تیمی یا گم کردن ابزارهای مشترک — به‌تنهایی جزئی به نظر می‌رسند. بااین‌حال وقتی روزانه و طی هفته‌ها یا ماه‌ها تکرار شوند، این ناراحتی‌های کوچک به تعارض‌های جدی شخصی بدل می‌شوند. فهم اینکه چرا آزارهای کوچکِ عادتی چنین واکنش‌های قوی‌ای برمی‌انگیزند، نخستین گام برای مدیریت مؤثرشان و حفظ رابطه‌های سالم است.\nدلیل روان‌شناختیِ سریع انباشته شدن آزارهای کوچک به شیوهٔ برخورد ذهن با استرس و مرزهای شخصی برمی‌گردد. وقتی کسی بارها کار آزارنده‌ای انجام می‌دهد، فرد درگیر کم‌کم پیش از وقوع هم انتظار مشکل را می‌کشد. همین انتظار دائمیِ دردسر، استرس خفیفِ پیوسته‌ای می‌سازد و فرد را نسبت به آن کنش حساس‌تر می‌کند. با گذر زمان، آن حواس‌پرتیِ جزئیِ اولیه شبیه نشانه‌ای عمدی از بی‌احترامی می‌شود. در نتیجه ممکن است سر ماجرای بسیار کوچکی دعوای تندی در بگیرد و کسی که باعثش بوده شگفت‌زده شود، چون نفهمیده بود چه‌قدر تنش در طول زمان انباشته شده است.\nبرای جلوگیری از آسیب آزارهای کوچک به رابطه‌های کاری و شخصی، افراد باید یاد بگیرند رفتارهای آزارنده را مؤدبانه مطرح کنند. ارتباط به‌موقع و صادقانه ضروری است. صبر کردن تا لحظهٔ فلج‌کنندهٔ کامل معمولاً به حرف‌های خشمگینی می‌انجامد که طرف مقابل را حالت دفاعی می‌برد. در عوض، مسئله را زود و با زبانی آرام و بی‌طرف مطرح کنید. تمرکزتان را بر یافتن راه‌حل عملی بگذارید، نه طلب کمال مطلق. مثلاً اگر سیستم شلوغ پرونده‌های یک هم‌تیمی پروژه‌های مشترک را کند می‌کند، یک سیستم ساده و مرتب پیشنهاد کنید که به هر دو کمک کند، به‌جای آنکه فقط از بی‌نظمی او گلایه کنید.\nدر برخورد با عادت‌هایی که به‌سادگی عوض نمی‌شوند، تغییر کانون ذهنی راهبردی بسیار سودمند است. این یعنی نادیده گرفتن مسئله‌های واقعی نیست، بلکه تنظیم نگاه برای کم کردن استرس شخصی است. وقتی می‌پذیرید که هر کس عادت‌های یکتا و ویژگی‌های گاه آزارنده دارد، انتظار کمال مطلق از دیگران را پایین می‌آورید. به یاد آوردن کارهای مثبت همکار، آزارهای کوچک عادتی را در وزن درست نگه می‌دارد و مانع می‌شود لحظه‌های زودگذرِ دلخوری، رابطهٔ کاری‌تان را خراب کند.\nافزون بر این، ساختن رابطه‌های تیمی محکم خودآگاهی صادقانه می‌طلبد. آدم‌ها معمولاً دیگران را به رفتار و خودشان را به نیت خوب می‌سنجند. شاید دیر رسیدن خودتان به جلسه را به‌پای شلوغی بگذارید، اما همان کار همکار خشمگین‌تان کند. پرورش درک متقابل به شما کمک می‌کند ببینید عادت‌های شما هم می‌تواند برای همکاران یا اعضای خانواده به همان اندازه آزاردهنده باشد. وقتی تیم‌ها فرهنگ فهم متقابل و بخشش می‌سازند، افراد راحت مشکلات را بی‌ترس از قضاوت تند در میان می‌گذارند. با گوش دادن فعال، گفت‌وگوی مؤدبانه و انعطاف شخصی، مردم می‌توانند تعارض‌های عادتی را به فرصتی برای کار تیمی قوی‌تر و رشد شخصی تبدیل کنند. گام برداشتن برای احترام به عادت‌های یکدیگر به موفقیت بلندمدت می‌انجامد. پذیرفتن تفاوت‌های کوچک به همه کمک می‌کند آرامش و بهره‌وری را حفظ کنند.", "glossary": {}, "hl": [], "gist": {"q": "What is the main idea of the article?", "o": ["Minor habit irritations build up over time due to stress expectations, but can be managed through early communication and self-awareness.", "Personal conflicts in offices are impossible to avoid and usually require changing jobs.", "Most employees disrupt shared spaces on purpose to irritate their colleagues.", "Perfection is required from every team member to achieve workplace harmony."], "a": 0}, "detailed": [{"q": "According to the text, why do small irritations cause explosive arguments eventually?", "o": ["Because people forget what started the original argument.", "Because constant anticipation of the disruption creates continuous stress over time.", "Because managers encourage employees to hold back their feelings.", "Because small habits always cost companies money."], "a": 1}, {"q": "What is recommended when bringing up a habit issue with a colleague?", "o": ["Wait until you are furious so they understand the severity.", "Bring it up early using calm, neutral language focused on practical solutions.", "Send an anonymous complaint to executive leadership.", "Demand that the person change their entire personality immediately."], "a": 1}, {"q": "How does judging ourselves versus judging others create misunderstandings?", "o": ["We judge others by their actions while judging ourselves by our good intentions.", "We always judge ourselves much more harshly than we judge others.", "We ignore our own work achievements while praising coworkers.", "We assume everyone else has perfect time-management skills."], "a": 0}]}];
LESSONS["1C"].writing={"prompts": [{"title": "Prompt 1", "text": "Describe a minor habit or behavior of a colleague or family member that you used to find frustrating. Explain how you brought up the issue or changed your perspective to resolve the situation, and what you learned from the experience."}, {"title": "Prompt 2", "text": "Write a response to a colleague who has approached you about a personal habit that is disrupting their work (e.g., talking loudly on calls or leaving items in shared spaces). Practice acknowledging their feelings politely, explaining your side diplomatically, and proposing a practical compromise."}]};
LESSONS["1C"].grammar={points:[{"label": "استراتژی ۱", "title": "Always + continuous — describing habits", "html": "<h3>قاعده</h3>\n<p>برای صحبت درباره‌ی عادت‌های تکراری یک شخص (که معمولاً کمی ما را آزرده می‌کند)، از ساختار <b>am/is/are always + فعل‌ing</b> استفاده می‌کنیم.</p>\n<div class=\"ex\">He's <span class=\"hl\">always smiling</span>. · He's <span class=\"hl\">always disturbing</span> people.</div>\n<div class=\"note\">این ساختار معمولاً نشان‌دهنده‌ی کمی آزردگی یا تعجب از یک عادت است، نه فقط توصیف خنثی.</div>"},{"label": "استراتژی ۲", "title": "At least — نکته‌ی مثبت در یک موقعیت", "html": "<h3>قاعده</h3>\n<p>از عبارت <b>at least</b> برای اشاره به نکته‌ی مثبت یک موقعیت منفی استفاده می‌کنیم.</p>\n<div class=\"ex\">\"He's always standing around and talking.\" → \"Well, <span class=\"hl\">at least</span> he's pleasant.\"</div>\n<div class=\"note\">at least یکی از ۵۰۰ عبارت پرکاربرد در انگلیسی محاوره‌ای است.</div>"}],bookExC4:[{"q": "Everyone in my family loves music. We sing together. → We ____ together.", "o": ["are always singing", "always sing"], "a": 0, "ex": "عادتی که کمی زیاده‌روی دارد → always + ing."}, {"q": "My brother is really generous with his time. He fixes my computer. → He ____ my computer.", "o": ["is always fixing", "always fixes"], "a": 0, "ex": ""}, {"q": "My father is a workaholic. He comes home late. → He ____ home late.", "o": ["is always coming", "always comes"], "a": 0, "ex": ""}, {"q": "My college roommate was really funny. She told jokes. → She ____ jokes.", "o": ["was always telling", "always told"], "a": 0, "ex": ""}, {"q": "A friend of mine complains she's broke, but she buys expensive clothes. → She ____ expensive clothes.", "o": ["is always buying", "always buys"], "a": 0, "ex": ""}, {"q": "One of my friends is totally unreliable. He cancels plans at the last minute. → He ____ plans at the last minute.", "o": ["is always canceling", "always cancels"], "a": 0, "ex": ""}],bookExC6:[{"q": "My girlfriend's always running behind, but she calls to say she'll be late. → Well, ____ she calls.", "o": ["at least", "at last"], "a": 0, "ex": ""}, {"q": "My best friend is always borrowing my clothes, but she returns them in good condition. → Well, ____ she returns them nicely.", "o": ["at least", "at all"], "a": 0, "ex": ""}, {"q": "One of my classmates talks about himself a lot, but his stories are always interesting. → Well, ____ his stories are interesting.", "o": ["at least", "at once"], "a": 0, "ex": ""}, {"q": "My roommate sleeps all the time, but she doesn't snore. → Well, ____ she doesn't snore!", "o": ["at least", "at all"], "a": 0, "ex": ""}, {"q": "My parents and I see things differently, but we don't have big fights. → Well, ____ we don't fight.", "o": ["at least", "at last"], "a": 0, "ex": ""}, {"q": "My boyfriend is always checking his messages, even at the movies! → At least he doesn't _____ it during the movie.", "o": ["answer", "lose"], "a": 0, "ex": "جواب نمی‌دهد به گوشی وسط فیلم."}, {"q": "My girlfriend is always telling jokes. → Well, at least she has a good sense of _____.", "o": ["humor", "time"], "a": 0, "ex": "have a great sense of humor."}, {"q": "I'm always losing pens and things. → Yeah, but at least you don't lose anything really _____.", "o": ["valuable", "cheap"], "a": 0, "ex": ""}, {"q": "My sister is always asking me for money. → Well, at least she asks _____.", "o": ["politely", "rudely"], "a": 0, "ex": "مکالمه می‌گوید she asks politely."}]};
LESSONS["1C"].sessions=[{"id": "cs1", "stage": "Coursebook", "icon": "💬", "title": "Conversation", "fa": "متن کامل مکالمه", "parts": [{"t": "context", "label": "Context", "title": "Max and Ellie talk about a co-worker", "lines": [{"sp": "Max", "text": "Hey, how are you getting along with your new co-worker? He seems extremely friendly. He's always smiling."}, {"sp": "Ellie", "text": "You mean Jim? Well, yeah, he is, but he never does any work. He's always disturbing people. It drives me crazy. You know, he's always standing around and talking."}, {"sp": "Max", "text": "Well, at least he's pleasant."}, {"sp": "Ellie", "text": "Yeah. And he's not always criticizing people like that last guy."}, {"sp": "Max", "text": "Yeah. He was pretty bad. He was always talking about people behind their backs."}, {"sp": "Ellie", "text": "I mean, at least Jim's not like that. But like, he's always wasting time."}, {"sp": "Max", "text": "You mean like we're doing right now?"}]}]}, {"id": "cs2", "stage": "Coursebook", "icon": "📝", "title": "Always + -ing", "fa": "توضیح: همیشه + ing", "parts": [{"t": "teach", "pts": [0]}]}, {"id": "cs3", "stage": "Coursebook", "icon": "👆", "title": "Find the pattern", "fa": "الگو را پیدا کنید", "parts": [{"t": "tapfind", "prompt": "Tap every line where Max or Ellie use always + -ing to describe a habit.", "lines": [{"sp": "Max", "text": "Hey, how are you getting along with your new co-worker? He seems extremely friendly. He's always smiling."}, {"sp": "Ellie", "text": "You mean Jim? Well, yeah, he is, but he never does any work. He's always disturbing people. It drives me crazy. You know, he's always standing around and talking."}, {"sp": "Max", "text": "Well, at least he's pleasant."}, {"sp": "Ellie", "text": "Yeah. And he's not always criticizing people like that last guy."}, {"sp": "Max", "text": "Yeah. He was pretty bad. He was always talking about people behind their backs."}, {"sp": "Ellie", "text": "I mean, at least Jim's not like that. But like, he's always wasting time."}, {"sp": "Max", "text": "You mean like we're doing right now?"}]}]}, {"id": "cs4", "stage": "Coursebook", "icon": "✅", "title": "Exercise", "fa": "تمرین D کتاب", "parts": [{"t": "bookExercise", "key": "bookExC4", "label": "Exercise"}]}, {"id": "cs5", "stage": "Coursebook", "icon": "➕", "title": "At Least", "fa": "توضیح: حداقل", "parts": [{"t": "teach", "pts": [1]}]}, {"id": "cs6", "stage": "Coursebook", "icon": "✅", "title": "More Practice", "fa": "تمرین «حداقل»", "parts": [{"t": "bookExercise", "key": "bookExC6", "label": "Exercise"}]}, {"id": "ex1", "stage": "Extra", "icon": "📚", "title": "Vocabulary 1", "fa": "لغات ۱", "parts": [{"t": "vocab", "from": 0, "to": 10}, {"t": "matching", "sets": [1, 2]}]}, {"id": "ex2", "stage": "Extra", "icon": "📚", "title": "Vocabulary 2", "fa": "لغات ۲", "parts": [{"t": "vocab", "from": 10, "to": 20}, {"t": "matching", "sets": [3, 4]}, {"t": "gap"}]}, {"id": "ex3", "stage": "Extra", "icon": "📖", "title": "Article 1", "fa": "مقاله ۱", "parts": [{"t": "reading", "text": 0}]}, {"id": "ex4", "stage": "Extra", "icon": "📖", "title": "Article 2", "fa": "مقاله ۲", "parts": [{"t": "reading", "text": 1}]}, {"id": "ex5", "stage": "Extra", "icon": "✍️", "title": "Writing", "fa": "نوشتن", "parts": [{"t": "writing"}]}];

