LESSONS["3B"].grammar={points:[{"label": "نقطه ۱", "title": "Questions with How + adjective ...?", "html": "<h3>قاعده</h3>\n<p>برای پرسیدن اندازه‌ی دقیق چیزی، از <b>How + صفت</b> استفاده می‌کنیم.</p>\n<div class=\"ex\">How high is Mount Everest? → It's 8,850 meters (29,035 feet) high.</div>\n<div class=\"ex\">How long is the Nile River? → It's 6,695 kilometers (4,160 miles) long.</div>\n<div class=\"ex\">How wide is the Grand Canyon? → It's about 29 kilometers (18 miles) wide.</div>\n<div class=\"ex\">How deep is the Pacific Ocean? → It's about 11,000 meters (36,000 feet) deep.</div>\n<div class=\"ex\">How hot does it get in Death Valley? → It can reach 48 degrees Celsius (120 degrees Fahrenheit).</div>"}, {"label": "نقطه ۲", "title": "Measurements + adjective", "html": "<h3>قاعده</h3>\n<p>بعد از یک عدد و واحد اندازه‌گیری، می‌توانیم صفتی مثل <b>high, tall, long, wide, deep</b> اضافه کنیم.</p>\n<div class=\"ex\">It's 8,850 meters <span class=\"hl\">high</span>. · It's 29 kilometers <span class=\"hl\">wide</span>.</div>"}],bookExA:[{"q": "How _____ is the Mackenzie River? — It's 4,241 kilometers long.", "o": ["long", "far"], "a": 0, "ex": ""}, {"q": "How high is Mount Aconcagua? — It's _____ meters high.", "o": ["6,962", "4,241"], "a": 0, "ex": ""}, {"q": "How _____ is Australia? — It's almost 7.7 million square kilometers.", "o": ["large", "tall"], "a": 0, "ex": ""}, {"q": "How wide is the Grand Canyon? — It's _____ kilometers wide.", "o": ["29", "6,962"], "a": 0, "ex": ""}, {"q": "How deep is Lake Baikal? — It's _____ meters deep.", "o": ["1,741", "29"], "a": 0, "ex": ""}, {"q": "How cold does it get in Antarctica? — It can reach _____ degrees Celsius.", "o": ["-89.6", "48"], "a": 0, "ex": ""}],buildingVocab:[{"q": "A large area of sand with very little rain is a...", "o": ["desert", "glacier"], "a": 0, "ex": ""}, {"q": "A group of islands close together is an...", "o": ["archipelago", "reef"], "a": 0, "ex": ""}, {"q": "A large area of trees that gets a lot of rain is a...", "o": ["rain forest", "coast"], "a": 0, "ex": ""}, {"q": "A large body of salt water, bigger than a sea, is an...", "o": ["ocean", "lake"], "a": 0, "ex": ""}, {"q": "A mountain that can erupt is a...", "o": ["volcano", "island"], "a": 0, "ex": ""}, {"q": "A large area of slowly-moving ice is a...", "o": ["glacier", "desert"], "a": 0, "ex": ""}, {"q": "Land completely surrounded by water is an...", "o": ["island", "coast"], "a": 0, "ex": ""}, {"q": "A structure of coral under the sea is a...", "o": ["reef", "river"], "a": 0, "ex": ""}, {"q": "The land next to the sea is the...", "o": ["coast", "mountain"], "a": 0, "ex": ""}, {"q": "A body of fresh water surrounded by land is a...", "o": ["lake", "ocean"], "a": 0, "ex": ""}],extraQuiz1:[{"q": "How _____ is the Amazon River?", "o": ["long", "far"], "a": 0, "ex": ""}, {"q": "It's about 6,400 kilometers _____.", "o": ["long", "longly"], "a": 0, "ex": ""}, {"q": "How _____ is K2? — It's 8,611 meters high.", "o": ["high", "tall only"], "a": 0, "ex": ""}, {"q": "How _____ is the Dead Sea? — It's about 430 meters below sea level.", "o": ["deep", "wide"], "a": 0, "ex": ""}, {"q": "How _____ is the Bering Strait? — It's about 82 kilometers wide.", "o": ["wide", "deep"], "a": 0, "ex": ""}, {"q": "How hot does it get in the Sahara? — It can reach 50 degrees _____.", "o": ["Celsius", "kilometers"], "a": 0, "ex": ""}, {"q": "How _____ is Lake Superior? — It's about 560 kilometers long.", "o": ["long", "high"], "a": 0, "ex": ""}, {"q": "It's 3,000 meters _____ at its deepest point.", "o": ["deep", "wide"], "a": 0, "ex": ""}, {"q": "How _____ is Angel Falls? — It's 979 meters high.", "o": ["high", "long"], "a": 0, "ex": ""}, {"q": "How _____ is the Strait of Gibraltar? — It's about 13 kilometers wide.", "o": ["wide", "deep"], "a": 0, "ex": ""}],extraQuiz2:[{"q": "How _____ is Lake Baikal? — It's 1,642 meters deep.", "o": ["deep", "wide"], "a": 0, "ex": ""}, {"q": "How _____ is the Yangtze River? — It's about 6,300 kilometers long.", "o": ["long", "high"], "a": 0, "ex": ""}, {"q": "How _____ is Denali? — It's 6,190 meters high.", "o": ["high", "deep"], "a": 0, "ex": ""}, {"q": "It's about 1,500 meters _____ at its widest point.", "o": ["wide", "long"], "a": 0, "ex": ""}, {"q": "How _____ does it get in Siberia in winter? — It can reach -50 degrees Celsius.", "o": ["cold", "hot"], "a": 0, "ex": ""}, {"q": "How _____ is the Mariana Trench? — It's about 11,000 meters deep.", "o": ["deep", "high"], "a": 0, "ex": ""}, {"q": "How _____ is the Great Barrier Reef? — It's about 2,300 kilometers long.", "o": ["long", "wide"], "a": 0, "ex": ""}, {"q": "How _____ is Ben Nevis? — It's 1,345 meters high.", "o": ["high", "long"], "a": 0, "ex": ""}, {"q": "It's about 160 kilometers _____ from end to end.", "o": ["long", "deep"], "a": 0, "ex": ""}, {"q": "How _____ is the Colorado River? — It's about 2,300 kilometers long.", "o": ["long", "wide"], "a": 0, "ex": ""}]};
LESSONS["3B"].convo1=[{"q": "What's an amazing natural place you've heard of or visited?", "sample": "I've always wanted to see the Grand Canyon in person — it's incredibly wide, like almost 29 kilometers across at some points, which is honestly hard to even picture. I haven't actually been there yet, but I've seen so many pictures and videos, and it looks absolutely amazing, like nothing else on earth. How deep do you think it actually is? I read somewhere that it's almost 1,800 meters deep in places, which just seems impossible until you see the photos. I'm hoping to finally go next year if everything works out — it's honestly at the top of my travel list right now.", "glossary": {}, "hl": ["wide", "deep", "kilometers", "meters"]}];
LESSONS["3B"].convo2=[{"q": "If you could visit any natural wonder in the world, which would you choose?", "sample": "Probably Mount Everest, if I'm being honest — even just to see it up close from a distance, not to climb it. It's so incredibly high, almost 8,850 meters, that it's genuinely hard to picture until you're standing near it. I definitely wouldn't want to actually climb it, though — that's a whole different level of adventure that I'm just not brave enough for! I'd also love to see the Sahara Desert someday; it's absolutely huge, something like 9 million square kilometers, which is bigger than a lot of entire countries put together. It's honestly hard to imagine how large that really is until you try to compare it to somewhere familiar.", "glossary": {}, "hl": ["high", "meters", "large", "square kilometers"]}];
LESSONS["3B"].sessions=[{"id": "cb1", "stage": "Coursebook", "icon": "💬", "title": "Did You Know...?", "fa": "متن: آیا می‌دانستید؟", "parts": [{"t": "context", "label": "Context", "title": "Did You Know...?", "lines": [{"sp": "Did you know...?", "text": "The Nile is the longest river in Africa. It's 6,695 kilometers (4,160 miles) long."}, {"sp": "Did you know...?", "text": "The highest mountain in the world is Mount Everest in Asia. It's 8,850 meters (29,035 feet) high."}, {"sp": "Did you know...?", "text": "The largest ocean is the Pacific. It covers one-third of the earth! The deepest part is about 11,000 meters (36,000 feet) deep."}, {"sp": "Did you know...?", "text": "The largest river (by area covered) is the Amazon in South America — about 4 million square kilometers (1.5 million square miles)."}, {"sp": "Did you know...?", "text": "The largest hot desert is the Sahara in Africa — about 9.1 million square kilometers (3.5 million square miles)."}, {"sp": "Did you know...?", "text": "The most active volcano is probably Kilauea, on the island of Hawai'i. It has been active since 1983, and it still erupts every day!"}]}]}, {"id": "cb2", "stage": "Coursebook", "icon": "⭕", "title": "Pre-test", "fa": "پیش‌آزمون", "parts": [{"t": "selfcheck", "key": "pretest", "label": "Pre-test"}]}, {"id": "cb3", "stage": "Coursebook", "icon": "📝", "title": "How + Adjective", "fa": "آموزش: How + صفت", "parts": [{"t": "teach", "pts": [0, 1]}]}, {"id": "cb4", "stage": "Coursebook", "icon": "✅", "title": "Exercise", "fa": "تمرین A کتاب", "parts": [{"t": "bookExercise", "key": "bookExA", "label": "Exercise"}]}, {"id": "cb5", "stage": "Coursebook", "icon": "🔁", "title": "Building Vocabulary", "fa": "تقویت واژگان", "parts": [{"t": "bookExercise", "key": "buildingVocab", "label": "Building Vocabulary"}]}, {"id": "ex1", "stage": "Extra", "icon": "📚", "title": "Vocabulary 1", "fa": "لغات ۱", "parts": [{"t": "vocab", "from": 0, "to": 10}, {"t": "matching", "sets": [1, 2]}]}, {"id": "ex2", "stage": "Extra", "icon": "📚", "title": "Vocabulary 2", "fa": "لغات ۲", "parts": [{"t": "vocab", "from": 10, "to": 20}, {"t": "matching", "sets": [3, 4]}, {"t": "gap"}]}, {"id": "ex3", "stage": "Extra", "icon": "🎯", "title": "Grammar Quiz 1", "fa": "آزمون گرامر ۱", "parts": [{"t": "quizset", "key": "extraQuiz1", "label": "Grammar Quiz 1"}]}, {"id": "ex4", "stage": "Extra", "icon": "🎯", "title": "Grammar Quiz 2", "fa": "آزمون گرامر ۲", "parts": [{"t": "quizset", "key": "extraQuiz2", "label": "Grammar Quiz 2"}]}, {"id": "ex5", "stage": "Extra", "icon": "🗣️", "title": "Conversation Practice 1", "fa": "تمرین مکالمه ۱", "parts": [{"t": "convo", "key": "convo1"}]}, {"id": "ex6", "stage": "Extra", "icon": "🗣️", "title": "Conversation Practice 2", "fa": "تمرین مکالمه ۲", "parts": [{"t": "convo", "key": "convo2"}]}, {"id": "ex7", "stage": "Extra", "icon": "📖", "title": "Article 1", "fa": "مقاله ۱", "parts": [{"t": "reading", "text": 0}]}, {"id": "ex8", "stage": "Extra", "icon": "📖", "title": "Article 2", "fa": "مقاله ۲", "parts": [{"t": "reading", "text": 1}]}, {"id": "ex9", "stage": "Extra", "icon": "✍️", "title": "Writing", "fa": "نوشتن", "parts": [{"t": "writing"}]}];

